// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.audio/** * NOUS — Audio format descriptor. * * All audio in NOUS uses **16 kHz, 16-bit, mono PCM** for the voice pipeline. * This is the de-facto standard for speech processing: *   - 16 kHz sample rate — sufficient for speech (max ~8 kHz frequency) *   - 16-bit depth — 96 dB dynamic range, no quantization noise *   - Mono — single channel, halves memory vs stereo * * The AudioTrack (TTS output) may use 44.1 kHz for richer sound effects, but * the voice pipeline (capture → STT → speaker recognition) is always 16 kHz. * * 20 ms chunks (= 320 samples at 16 kHz) is the universal frame size used by: *   - WebRTC AEC *   - RNNoise *   - VAD *   - ECAPA-TDNN *   - VAP model * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */data class AudioFormat(    /** Samples per second. Default: 16000. */    val sampleRateHz: Int = DEFAULT_SAMPLE_RATE,    /** Bits per sample. Default: 16. */    val bitsPerSample: Int = DEFAULT_BITS_PER_SAMPLE,    /** Number of channels. Always 1 (mono) for voice pipeline. */    val channels: Int = DEFAULT_CHANNELS,) {    /** Bytes per sample = bitsPerSample / 8. */    val bytesPerSample: Int get() = bitsPerSample / 8    /** Bytes per second = sampleRate × bytesPerSample × channels. */    val bytesPerSecond: Int get() = sampleRateHz * bytesPerSample * channels    /** Samples per 20 ms chunk (universal frame size for voice processing). */    val samplesPerFrame: Int get() = sampleRateHz * FRAME_DURATION_MS / 1000    /** Bytes per 20 ms chunk. */    val bytesPerFrame: Int get() = samplesPerFrame * bytesPerSample * channels    /** Frame duration in milliseconds. */    val frameDurationMs: Int get() = FRAME_DURATION_MS    init {        require(sampleRateHz in 8000..48000) {            "sampleRateHz must be 8000-48000, got $sampleRateHz"        }        require(bitsPerSample == 16 || bitsPerSample == 8 || bitsPerSample == 24 || bitsPerSample == 32) {            "bitsPerSample must be 8/16/24/32, got $bitsPerSample"        }        require(channels >= 1 && channels <= 2) {            "channels must be 1 or 2, got $channels"        }    }    companion object {        /** Standard NOUS voice format: 16 kHz, 16-bit, mono. */        val VOICE_16K = AudioFormat(            sampleRateHz = 16_000,            bitsPerSample = 16,            channels = 1,        )        /** Sound effects format: 44.1 kHz, 16-bit, mono. */        val SFX_44K = AudioFormat(            sampleRateHz = 44_100,            bitsPerSample = 16,            channels = 1,        )        /** Universal frame duration for voice processing. */        const val FRAME_DURATION_MS = 20        const val DEFAULT_SAMPLE_RATE = 16_000        const val DEFAULT_BITS_PER_SAMPLE = 16        const val DEFAULT_CHANNELS = 1    }}